828	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data). The prefix byte and
829	/// the record are fed to the hasher as two consecutive slices, so hashing a
830	/// record of any length needs no copy of the record and no allocation beyond
831	/// the hasher's fixed-size state.
832	fn leaf_hash(data: &[u8]) -> [u8; 32] {
833	    let mut h = new_leaf_hasher();
834	    h.update(data);
835	    h.finalize()
836	}
