838	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
839	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
840	    let mut h = Sha256::new();
841	    h.update(&[0x01]);
842	    h.update(left);
843	    h.update(right);
844	    h.finalize()
845	}
