847	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
848	/// that maintains the tree-construction rules: both `root` (via `mth`) and
849	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
850	/// two commands can never disagree on how a batch is shaped or hashed.
851	///
852	/// ```text
853	/// MTH([])      = SHA-256("")
854	/// MTH([d])     = SHA-256(0x00 || d)
855	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
856	/// ```
857	///
858	/// with k the largest power of two strictly smaller than n. Uneven batches
859	/// are handled by the recursion itself: no leaf is duplicated and no empty
860	/// record is appended to round the size up to a power of two.
861	///
862	/// `target` selects the one leaf a membership proof is built for:
863	///
864	/// ```text
865	/// PATH(m, [d0]) = []
866	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
867	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
868	/// ```
869	///
870	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
871	/// leaf `m` to the root are appended to `path` in leaf-to-root order
872	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
873	/// leaf into whichever subtree contains it, while the sibling subtree is
874	/// built with `None`. With `None` only the root is built. Every leaf hash and
875	/// every interior hash is computed exactly once in either mode, so producing
876	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
877	fn build_tree(
878	    leaves: &[&[u8]],
879	    target: Option<usize>,
880	    path: &mut Vec<[u8; 32]>,
881	) -> [u8; 32] {
882	    match leaves.len() {
883	        0 => sha256(&[]),
884	        1 => leaf_hash(leaves[0]),
885	        n => {
886	            // Largest power of two strictly smaller than n.
887	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
888	            let (left_leaves, right_leaves) = leaves.split_at(k);
889	            match target {
890	                // The audited leaf is in the left subtree; the right subtree
891	                // hash is this level's sibling on the leaf-to-root path.
892	                Some(m) if m < k => {
893	                    let left = build_tree(left_leaves, Some(m), path);
894	                    let right = build_tree(right_leaves, None, path);
895	                    path.push(right);
896	                    node_hash(&left, &right)
897	                }
898	                // The audited leaf is in the right subtree; reindex it
899	                // relative to that subtree and take the left subtree as the
900	                // sibling.
901	                Some(m) => {
902	                    let left = build_tree(left_leaves, None, path);
903	                    let right = build_tree(right_leaves, Some(m - k), path);
904	                    path.push(left);
905	                    node_hash(&left, &right)
906	                }
907	                // No audited leaf: both subtrees are plain root constructions.
908	                None => {
909	                    let left = build_tree(left_leaves, None, path);
910	                    let right = build_tree(right_leaves, None, path);
911	                    node_hash(&left, &right)
912	                }
913	            }
914	        }
915	    }
916	}
