939	// --- Streaming root computation ---------------------------------------------
940	//
941	// `roottrace root` must not hold the batch in memory: the file is read through
942	// a fixed-size buffer and pushed through the shared [`RecordScanner`]. Every
943	// record is hashed as its bytes stream past (a record is never stored, however
944	// long it is), and the only per-record state the sink keeps is the stack of
945	// completed subtree hashes below — at most one entry per bit of the record
946	// count, so O(log n) hashes independent of the file's byte length and of the
947	// longest record. Record division itself lives entirely in `RecordScanner`,
948	// which is the exact code `prove`'s `split_records` drives.
949	
950	/// Incremental RFC 6962 Merkle Tree Hash over an LF-separated byte stream.
951	///
952	/// Bytes are fed through [`RootStream::feed`] in chunks of any size; how many
953	/// bytes one read returns is meaningless to the result, and a record that
954	/// spans any number of chunks is hashed in full. The LF/empty-record/trailing
955	/// rule is applied by the shared [`RecordScanner`], exactly as
956	/// [`split_records`] applies it to a whole batch, and the tree is folded with
957	/// the same largest-power-of-two split as `build_tree`, so
958	/// [`RootStream::finish`] returns exactly `mth(&split_records(whole))` for the
959	/// concatenation `whole` of everything fed.
960	///
961	/// Memory use is the read buffer plus a small fixed amount and at most 64
962	/// subtree hashes (one per bit of the record count): nothing grows with the
963	/// number of bytes fed or with the length of any single record.
964	#[doc(hidden)]
965	pub struct RootStream {
966	    /// The shared divider, feeding this stream's hashing sink.
967	    scanner: RecordScanner<StreamSink>,
968	}
969	
970	/// [`RecordSink`] for the streaming root: hash content into the open leaf and
971	/// fold one leaf per finished record into the subtree stack.
972	struct StreamSink {
973	    /// Hasher for the record currently being accumulated, primed with 0x00.
974	    /// It stays primed even before any content arrives, so an LF-terminated
975	    /// empty record hashes to SHA-256(0x00).
976	    leaf: Sha256,
977	    /// Completed subtree hashes, bottom to top in strictly decreasing height;
978	    /// entry i covers 2^height consecutive leaves. Together the entries are
979	    /// the binary decomposition of the record count so far, which is exactly
980	    /// the shape the recursive largest-power-of-two split produces.
981	    subtrees: Vec<([u8; 32], u32)>,
