1001	impl StreamSink {
1002	    fn new() -> Self {
1003	        StreamSink {
1004	            leaf: new_leaf_hasher(),
1005	            subtrees: Vec::new(),
1006	        }
1007	    }
1008	
1009	    /// Close the current record: finalize its leaf hash and fold it into the
1010	    /// subtree stack, merging completed subtrees of equal height so the stack
1011	    /// always holds the largest complete subtrees on the left.
1012	    fn finish_record(&mut self) {
1013	        let leaf = std::mem::replace(&mut self.leaf, new_leaf_hasher()).finalize();
1014	        let mut acc = leaf;
1015	        let mut height = 0u32;
1016	        while self.subtrees.last().is_some_and(|&(_, h)| h == height) {
1017	            let (left, _) = self.subtrees.pop().unwrap();
1018	            acc = node_hash(&left, &acc);
1019	            height += 1;
1020	        }
1021	        self.subtrees.push((acc, height));
1022	    }
1023	
1024	    /// Fold the completed subtrees into the batch root. No record means the
1025	    /// RFC 6962 empty-tree hash SHA-256("").
1026	    fn root(mut self) -> [u8; 32] {
1027	        match self.subtrees.pop() {
1028	            None => sha256(&[]),
1029	            Some((mut acc, _)) => {
1030	                // Fold the remaining complete subtrees right to left: reading
1031	                // the binary decomposition of the record count this way is
1032	                // the recursive k-split of build_tree.
1033	                while let Some((left, _)) = self.subtrees.pop() {
1034	                    acc = node_hash(&left, &acc);
1035	                }
1036	                acc
1037	            }
1038	        }
1039	    }
1040	}
