1291	    /// Verify an RFC 6962 inclusion proof with the RFC's recursive verifier:
1292	    /// it re-derives the combination order from the tree geometry (k =
1293	    /// largest power of two below the current subtree size) while consuming
1294	    /// exactly the supplied sibling hashes. A wrong length, order or hash
1295	    /// fails; the root computed here must equal the tree root.
1296	    fn rfc_recompute_root(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
1297	        assert!(m < n);
1298	        fn sub(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]], pos: &mut usize) -> [u8; 32] {
1299	            if n == 1 {
1300	                return leaf_hash(leaf);
1301	            }
1302	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
1303	            if m < k {
1304	                let left = sub(leaf, m, k, path, pos);
1305	                assert!(*pos < path.len(), "proof too short");
1306	                let right = path[*pos];
1307	                *pos += 1;
1308	                node_hash(&left, &right)
1309	            } else {
1310	                let right = sub(leaf, m - k, n - k, path, pos);
1311	                assert!(*pos < path.len(), "proof too short");
1312	                let left = path[*pos];
1313	                *pos += 1;
1314	                node_hash(&left, &right)
1315	            }
1316	        }
1317	        let mut pos = 0;
1318	        let root = sub(leaf, m, n, path, &mut pos);
1319	        assert_eq!(pos, path.len(), "proof too long: {pos} consumed of {}", path.len());
1320	        root
1321	    }
