75	fn proof_json(size: u64, index: u64, root: &str, path: &[&str]) -> String {
76	    let mut out =
77	        format!("{{\"tree_size\":{size},\"leaf_index\":{index},\"root\":\"{root}\",\"audit_path\":[");
78	    for (i, h) in path.iter().enumerate() {
79	        if i > 0 {
80	            out.push(',');
81	        }
82	        out.push('"');
83	        out.push_str(h);
84	        out.push('"');
85	    }
86	    out.push_str("]}");
87	    out
88	}
