90	fn run(
91	    record: &std::path::Path,
92	    proof: &std::path::Path,
93	    size: &str,
94	    root: &str,
95	) -> std::process::Output {
96	    Command::new(common::bin())
97	        .arg("verify")
98	        .arg(record)
99	        .arg(proof)
100	        .arg(size)
101	        .arg(root)
102	        .output()
103	        .expect("failed to execute roottrace binary")
104	}
