258	/// LF-split a batch exactly like the documented root/prove rule, purely for
259	/// producing the expected record files in this test.
260	fn nth_file_records(data: &[u8]) -> Vec<&[u8]> {
261	    if data.is_empty() {
262	        return Vec::new();
263	    }
264	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
265	    if data.last() == Some(&b'\n') {
266	        records.pop();
267	    }
268	    records
269	}
270	
271	fn nth_record(data: &[u8], index: u64) -> Vec<u8> {
272	    nth_file_records(data)[index as usize].to_vec()
273	}
