307	fn record_file_is_used_verbatim_without_lf_splitting_or_trimming() {
308	    let empty_pos2 = proof_for_index(2, ROOT_B9);
309	    // Zero-byte record file is the empty record and verifies.
310	    assert_verified("zero-byte file", b"", &empty_pos2, "9", ROOT_B9);
