315	    assert_verification_failed("empty + CR", b"\r", &empty_pos2, "9", ROOT_B9);
316	    assert_verification_failed("empty + NUL", b"\x00", &empty_pos2, "9", ROOT_B9);
317	
318	    // A normal record with an extra terminating LF must fail.
