330	        proof_json(9, 0, ROOT_B9, PATH_B9_M0).as_bytes(),
331	        "9",
332	        ROOT_B9,
333	    );
334	
335	    // Binary record through real prove interop: NUL/non-UTF-8/CR preserved.
336	    let batch = TempFile::create(PAYLOAD_B9);
337	    let proved = Command::new(common::bin())
338	        .arg("prove")
339	        .arg(&batch.path)
340	        .arg("6")
