170	    for bad in &malformed {
171	        match verify_membership(BATCH_RECORDS[1], bad, size, &root) {
172	            Err(VerifyError::MalformedProof(_)) => {}
173	            other => panic!("{} must be MalformedProof, got {other:?}", String::from_utf8_lossy(bad)),
174	        }
175	    }
176	
177	    // Well-formed proofs that do not establish inclusion: wrong record,
178	    // wrong trusted size, wrong trusted root, wrong position, short path.
179	    let mut wrong_root = root;
180	    wrong_root[0] ^= 0x01;
181	    let moved = text.replace("\"leaf_index\":1", "\"leaf_index\":2");
182	    // Drop the first audit-path hash entirely: one hash short.
183	    let short = rebuild_without_first_path_hash(&text);
184	    let failures: Vec<(&[u8], Vec<u8>, u64, [u8; 32])> = vec![
185	        (b"not-the-record", proof.clone(), size, root),
186	        (BATCH_RECORDS[1], proof.clone(), size + 1, root),
187	        (BATCH_RECORDS[1], proof.clone(), size, wrong_root),
188	        (BATCH_RECORDS[1], moved.into_bytes(), size, root),
189	        (BATCH_RECORDS[1], short.into_bytes(), size, root),
190	    ];
191	    for (record, proof, size, root) in failures {
192	        match verify_membership(record, &proof, size, &root) {
193	            Err(VerifyError::VerificationFailed(_)) => {}
194	            other => panic!("must be VerificationFailed, got {other:?}"),
195	        }
196	    }
197	}
