199	fn roottrace_hex(root: &[u8; 32]) -> String {
200	    root.iter().map(|b| format!("{b:02x}")).collect()
201	}
202	
203	fn first_path_hash(proof: &str) -> String {
204	    let start = proof.find("\"audit_path\":[\"").unwrap() + "\"audit_path\":[\"".len();
205	    proof[start..start + 64].to_string()
206	}
207	
208	fn rebuild_without_first_path_hash(proof: &str) -> String {
209	    let first = first_path_hash(proof);
210	    proof.replacen(&format!("\"{first}\","), "", 1)
211	}
