213	// --- record bytes are verbatim ----------------------------------------------
214	
215	#[test]
216	fn library_record_bytes_are_verbatim() {
217	    let batch = batch_file();
218	    let root = batch_root();
219	    let size = BATCH_RECORDS.len() as u64;
220	
221	    // The empty record at position 2 verifies from an EMPTY byte slice.
222	    let proof = cli_proof(&batch, 2);
223	    let m = verify_membership(b"", &proof, size, &root).expect("empty record");
224	    assert_eq!(m.leaf_index(), 2);
225	
226	    // Appending LF, CR, space or NUL changes the record: verification fails.
227	    let proof = cli_proof(&batch, 1);
228	    for suffix in [b"\n".as_slice(), b"\r", b" ", b"\x00"] {
229	        let mut longer = BATCH_RECORDS[1].to_vec();
230	        longer.extend_from_slice(suffix);
231	        assert!(
232	            matches!(
233	                verify_membership(&longer, &proof, size, &root),
234	                Err(VerifyError::VerificationFailed(_))
235	            ),
236	            "record + trailing {suffix:?} must fail"
237	        );
238	    }
239	
240	    // The binary record (NUL + non-UTF-8 bytes) verifies as-is; one flipped
241	    // byte fails.
242	    let bin = BATCH_RECORDS[3];
243	    let proof = cli_proof(&batch, 3);
244	    assert!(verify_membership(bin, &proof, size, &root).is_ok());
245	    let mut tampered = bin.to_vec();
246	    *tampered.last_mut().unwrap() ^= 0x01;
247	    assert!(matches!(
248	        verify_membership(&tampered, &proof, size, &root),
249	        Err(VerifyError::VerificationFailed(_))
250	    ));
251	}
252	
253	// --- proof surface syntax: reorder, whitespace, escapes ---------------------
254	
255	#[test]
256	fn library_accepts_reordered_whitespace_and_escaped_proofs() {
257	    let batch = batch_file();
258	    let root = batch_root();
259	    let size = BATCH_RECORDS.len() as u64;
260	    let proof = cli_proof(&batch, 1);
261	    let text = String::from_utf8(proof).unwrap();
262	
263	    // Pretty-printed with reordered fields: parse the compact form apart and
264	    // re-emit it with different order and whitespace.
265	    let root_hex = roottrace_hex(&root);
266	    let path_hashes: Vec<String> = {
267	        let start = text.find("\"audit_path\":[").unwrap() + "\"audit_path\":[".len();
268	        let end = text[start..].find(']').unwrap() + start;
269	        text[start..end]
270	            .split(',')
271	            .map(|s| s.trim_matches('"').to_string())
272	            .collect()
273	    };
274	    let mut pretty = String::from("  {\n  \"audit_path\" : [ ");
275	    for (i, h) in path_hashes.iter().enumerate() {
276	        if i > 0 {
277	            pretty.push_str(" , ");
278	        }
279	        pretty.push('"');
280	        pretty.push_str(h);
281	        pretty.push('"');
282	    }
283	    pretty.push_str(&format!(
284	        " ] ,\n  \"root\" : \"{root_hex}\",\n  \"leaf_index\" : 1 ,\n  \"tree_size\" : {size}\n}}\n"
285	    ));
286	    let m = verify_membership(BATCH_RECORDS[1], pretty.as_bytes(), size, &root)
287	        .expect("reordered/pretty proof must verify");
288	    assert_eq!(m.leaf_index(), 1);
289	
290	    // Equivalent \uXXXX escapes in keys and hash characters: spell the first
291	    // character of the root hash as its \uXXXX escape.
292	    let escaped_root = format!("\\u{:04x}{}", root_hex.as_bytes()[0], &root_hex[1..]);
293	    let escaped = text
294	        .replace("\"tree_size\"", "\"tree_siz\\u0065\"")
295	        .replacen(&root_hex, &escaped_root, 1);
296	    assert!(verify_membership(BATCH_RECORDS[1], escaped.as_bytes(), size, &root).is_ok());
297	
298	    // Duplicate fields stay rejected, even when one copy is escaped.
299	    let dup = text.replace(
300	        "\"leaf_index\":1",
301	        "\"leaf_index\":1,\"leaf_inde\\u0078\":1",
302	    );
303	    assert!(matches!(
304	        verify_membership(BATCH_RECORDS[1], dup.as_bytes(), size, &root),
305	        Err(VerifyError::MalformedProof(_))
306	    ));
307	}
