311	#[test]
312	fn library_duplicate_content_is_verified_at_the_claimed_position_only() {
313	    let batch = batch_file();
314	    let root = batch_root();
315	    let size = BATCH_RECORDS.len() as u64;
316	    // "x" sits at positions 0 and 4. Each proof verifies only its own
317	    // position; the other position's proof must not substitute.
318	    let proof0 = cli_proof(&batch, 0);
319	    let proof4 = cli_proof(&batch, 4);
320	    assert_ne!(proof0, proof4, "same content, different positions, different proofs");
321	    assert_eq!(verify_membership(b"x", &proof0, size, &root).unwrap().leaf_index(), 0);
322	    assert_eq!(verify_membership(b"x", &proof4, size, &root).unwrap().leaf_index(), 4);
323	    // Reclaiming position 0 with the position-4 proof (edit leaf_index) fails.
324	    let moved = String::from_utf8(proof4).unwrap().replace("\"leaf_index\":4", "\"leaf_index\":0");
325	    assert!(matches!(
326	        verify_membership(b"x", moved.as_bytes(), size, &root),
327	        Err(VerifyError::VerificationFailed(_))
328	    ));
329	}
