331	// --- 64-bit sizes and indices are never truncated ---------------------------
332	//
333	// The same synthetic big-tree proofs as tests/verify_big_tree_regression.rs:
334	// the trusted roots are fixed constants generated by
335	// tests/reference/rfc6962_vectors.py with two independent implementations.
336	
337	const BIG_TREE_RECORD: &[u8] = b"big-tree-record\x00\xff\xfe";
338	
339	struct BigCase {
340	    size: u64,
341	    index: u64,
342	    depth: usize,
343	    root: &'static str,
344	}
345	
346	const BIG_TREE_CASES: &[BigCase] = &[
347	    // 2**63 (power-of-two tree), record 2**32 (first index past 32 bits).
348	    BigCase { size: 9223372036854775808, index: 4294967296, depth: 63, root: "afcfe7edcae41e08965824b245fd42bd162c459feecedd1bf581349b664d8ebe" },
349	    // 2**63+1 (uneven), last record = lone right subtree, one-hash path.
350	    BigCase { size: 9223372036854775809, index: 9223372036854775808, depth: 1, root: "e3004442ff263eaa1f454e07a87f17253cb9aadc06d4e2df78e23db1b3f82fd3" },
351	    // 2**64-1 (uneven), first record.
352	    BigCase { size: 18446744073709551615, index: 0, depth: 64, root: "00374def40979015a9865a6e90b2fbd6effc8e235befab92877dcdf5e63f0361" },
353	    // 2**64-1 (uneven), last record.
354	    BigCase { size: 18446744073709551615, index: 18446744073709551614, depth: 63, root: "c035bef423e3cc7dcaa0a23687221787e739ef1ad6717b6c9e562addde480fc6" },
355	];
356	
357	fn big_proof(case: &BigCase) -> Vec<u8> {
358	    let mut out = format!(
359	        "{{\"tree_size\":{},\"leaf_index\":{},\"root\":\"{}\",\"audit_path\":[",
360	        case.size, case.index, case.root
361	    );
362	    for i in 0..case.depth {
363	        if i > 0 {
364	            out.push(',');
365	        }
366	        out.push_str(&format!("\"{i:064x}\""));
367	    }
368	    out.push_str("]}");
369	    out.into_bytes()
370	}
371	
372	#[test]
373	fn library_big_tree_sizes_and_indices_keep_64bit_meaning() {
374	    for case in BIG_TREE_CASES {
375	        let proof = big_proof(case);
376	        let root = hash_of(case.root);
377	        let m = verify_membership(BIG_TREE_RECORD, &proof, case.size, &root).unwrap_or_else(|e| {
378	            panic!("tree_size={} leaf_index={} must verify: {e}", case.size, case.index)
379	        });
380	        // The full-width values come back untruncated.
381	        assert_eq!(m.leaf_index(), case.index);
382	        assert_eq!(m.tree_size(), case.size);
383	        assert_eq!(m.root(), &root);
384	
385	        // Off-by-one trusted size fails rather than truncating.
386	        assert!(matches!(
387	            verify_membership(BIG_TREE_RECORD, &proof, case.size - 1, &root),
388	            Err(VerifyError::VerificationFailed(_))
389	        ));
390	        // Off-by-one claimed index fails rather than wrapping. (The last
391	        // record of the 2^64-1 tree cannot move up: index == tree_size is a
392	        // format error, so that case moves down instead.)
393	        let off_index = if case.index + 1 < case.size {
394	            case.index + 1
395	        } else {
396	            case.index - 1
397	        };
398	        let moved_proof = String::from_utf8(big_proof(case))
399	            .unwrap()
400	            .replace(
401	                &format!("\"leaf_index\":{}", case.index),
402	                &format!("\"leaf_index\":{off_index}"),
403	            );
404	        assert!(matches!(
405	            verify_membership(BIG_TREE_RECORD, moved_proof.as_bytes(), case.size, &root),
406	            Err(VerifyError::VerificationFailed(_))
407	        ));
408	    }
409	}
